import openpyxl,json,collections
w=openpyxl.load_workbook('china-university-directory-1412-official-links-2026-10-06-v78.xlsx',data_only=True,read_only=True);s=w['รายชื่อ 1412'];rows=list(s.iter_rows(min_row=5,max_row=1416,values_only=True));cov=[r for r in rows if any(r[i] for i in (5,6,7))];print('rows',len(rows),'unique_MOE',len(set(r[2] for r in rows)),'covered',len(cov),'blank',len(rows)-len(cov));print('v78_target',[(r[2],r[3],r[5:8]) for r in rows if r[2] in ('4113010075','4113010086','4113011420','4113011903')]);ev=[json.loads(x) for x in open('official-source-evidence-2026-10-06.jsonl',encoding='utf-8') if x.strip()];print('evidence_rows',len(ev),'latest12',len(ev[-12:]),'latest_links',collections.Counter(x['link_type'] for x in ev[-12:]));print('last4',[(c, sum(1 for e in ev[-12:] if e['moe_code']==c)) for c in ('4113010075','4113010086','4113011420','4113011903')]);print('top_blanks',collections.Counter(r[0] for r in rows if not any(r[j] for j in (5,6,7))).most_common(8))
